import 'dart:ui' as ui;import 'package:flutter/material.dart';import 'package:flutter/rendering.dart';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_core/original_assets.dart';
void main(){Widget app(Widget child)=>MaterialApp(home:Center(child:child));
 test('central names, aliases and package descriptors are validated',(){expect(originalAssetNames.length,121);expect(originalAssetInfo('calendar')['bundleKey'],'packages/primecare_ui/assets/original/icons/calendar.svg');expect(resolveOriginalAsset('building'),'tenant');expect(resolveOriginalAsset('push-pin'),'pin-panel');expect(originalAssetInfo('arrow-right')['rtlMirror'],true);expect(originalAssetInfo('phone')['rtlMirror'],false);for(final name in ['unknown','constructor','../phone','Phone']){expect(()=>resolveOriginalAsset(name),throwsArgumentError);}expect(()=>originalAssetInfo('calendar')['viewBox']=[],throwsUnsupportedError);});
 testWidgets('all 121 canonical assets render without SVG/network dependencies',(t)async{for(final name in originalAssetNames){await t.pumpWidget(app(PrimeOriginalAsset(name,width:64,height:64)));await t.pump();expect(t.takeException(),isNull,reason:name);}expect(find.byType(CustomPaint),findsWidgets);});
 testWidgets('meaningful labels and decorative exclusion preserve accessibility',(t)async{final handle=t.ensureSemantics();await t.pumpWidget(app(const PrimeOriginalAsset('calendar',size:48,decorative:false,semanticLabel:'Registered calendar')));expect(find.bySemanticsLabel('Registered calendar'),findsOneWidget);await t.pumpWidget(app(const PrimeOriginalAsset('calendar',size:48)));expect(find.bySemanticsLabel('Registered calendar'),findsNothing);await t.pumpWidget(app(const PrimeOriginalAsset('calendar',size:48,decorative:false)));expect(t.takeException(),isA<ArgumentError>());handle.dispose();});
 testWidgets('raster tint and RTL mirroring agree with explicit geometry policy',(t)async{Future<List<int>> render(String name,TextDirection direction)async{final key=GlobalKey();await t.pumpWidget(app(RepaintBoundary(key:key,child:PrimeOriginalAsset(name,size:48,width:48,height:48,color:const Color(0xffc02030),direction:direction))));await t.pump();final boundary=t.renderObject<RenderRepaintBoundary>(find.byKey(key));return (await t.runAsync<List<int>>(()async{final image=await boundary.toImage(pixelRatio:1),bytes=await image.toByteData(format:ui.ImageByteFormat.rawRgba);image.dispose();return bytes!.buffer.asUint8List().toList();}))!;}final ltr=await render('arrow-right',TextDirection.ltr),rtl=await render('arrow-right',TextDirection.rtl);expect(ltr.where((v)=>v>0),isNotEmpty);var coloured=0,difference=0;for(var y=0;y<48;y++){for(var x=0;x<48;x++){final i=(y*48+x)*4,j=(y*48+47-x)*4;if(ltr[i+3]>200){expect(ltr[i],greaterThan(150));expect(ltr[i+1],lessThan(80));coloured++;}for(var c=0;c<4;c++){difference+=(ltr[i+c]-rtl[j+c]).abs();}}}expect(coloured,greaterThan(20));expect(difference/(48*48*4),lessThan(2));final phoneLtr=await render('phone',TextDirection.ltr),phoneRtl=await render('phone',TextDirection.rtl);expect(phoneLtr,phoneRtl);});
}
